&lt;li&gt;&lt;span class=&quot;TextRun SCXW187008655 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;In addition to &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW187008655 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;the significant stock option package, the estimated salary range for this role is &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;$&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;95&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;,000-$110&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW187008655 BCX0&quot;&gt;,000, &lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;dependent on the candidate&#39;s academic level (Bachelors, Masters, or PhD) and demonstrated out of classroom experience.&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW187008655 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
