&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We offer a unique opportunity to be an early and integral member of a rapidly growing company that is scaling world-changing technology.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
